insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('activities','activities',true,5242880,array['image/jpeg','image/png','image/webp']) on conflict(id) do update set public=true;
drop policy if exists "activity_public" on storage.objects;drop policy if exists "activity_insert" on storage.objects;drop policy if exists "activity_update" on storage.objects;drop policy if exists "activity_delete" on storage.objects;
create policy "activity_public" on storage.objects for select using(bucket_id='activities');create policy "activity_insert" on storage.objects for insert to authenticated with check(bucket_id='activities');create policy "activity_update" on storage.objects for update to authenticated using(bucket_id='activities');create policy "activity_delete" on storage.objects for delete to authenticated using(bucket_id='activities');
create table if not exists public.report_snapshots(id uuid primary key default gen_random_uuid(),token text unique not null,report_no text unique not null,period_start date not null,period_end date not null,fund_id uuid references public.funds(id),total_income numeric(14,2) default 0,total_expense numeric(14,2) default 0,row_count int default 0,created_by uuid references auth.users(id),created_at timestamptz default now());alter table public.report_snapshots enable row level security;drop policy if exists "report_public" on public.report_snapshots;drop policy if exists "report_insert" on public.report_snapshots;create policy "report_public" on public.report_snapshots for select using(true);create policy "report_insert" on public.report_snapshots for insert to authenticated with check(true);grant select on public.report_snapshots to anon,authenticated;grant insert on public.report_snapshots to authenticated;
